-- Daily challenges for 2026-10-20: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-20. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-room-for-quiet', 'Making Room for Quiet', 'For anyone whose days are full of noise, screens and chatter. Each day is one small way to find a pocket of quiet, from a silent first sip of coffee to a walk without headphones, so your mind gets a little room to settle.', 'Mindfulness', 365, array['Mindfulness', 'Stress', 'Self-Care']::text[], 1, '2026-10-20T17:00:00+00:00'::timestamptz),
  ('letting-kindness-in', 'Letting Kindness In', 'For anyone who is quick to help others but brushes off compliments, offers and thanks. Each day is one small practice in receiving: saying a simple thank you, accepting a hand, and letting care from other people land.', 'Self-Compassion', 365, array['Self-Esteem', 'Self-Compassion', 'Relationships']::text[], 1, '2026-10-20T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-room-for-quiet', 'letting-kindness-in');

